//! Integration tests for the bundled PDF test fixtures.
//!
//! The fixtures in `tests/pdfs/fixtures/` are generated by
//! `scripts/make_test_pdfs.py` (reportlab). They are part of the repo so the
//! PDF converters can be exercised against real, designed documents rather
//! than hand-made byte strings.

use cleanup_convert::{Target, convert};
use cleanup_core::FormatId;
use cleanup_formats::{cluster_lines, pdf_layout};
use std::path::{Path, PathBuf};

fn fixtures_dir() -> PathBuf {
    PathBuf::from(std::env::var("CARGO_MANIFEST_DIR").unwrap()).join("tests/pdfs/fixtures")
}

fn fixture_names() -> Vec<String> {
    let mut names = Vec::new();
    for entry in std::fs::read_dir(fixtures_dir()).expect("fixtures directory exists") {
        let entry = entry.expect("fixture entry");
        let path = entry.path();
        if path.extension().and_then(|s| s.to_str()) == Some("pdf") {
            names.push(path.file_name().unwrap().to_string_lossy().into_owned());
        }
    }
    names.sort();
    names
}

/// Extract readable text from a fixture PDF via our native layout parser.
fn extract_text(path: &Path) -> String {
    let bytes = std::fs::read(path).expect("fixture readable");
    let layout =
        pdf_layout(&bytes).unwrap_or_else(|e| panic!("{}: pdf_layout failed: {e}", path.display()));
    assert!(layout.pages.len() >= 1, "{}: no pages", path.display());
    let mut text = String::new();
    for page in &layout.pages {
        for line in cluster_lines(&page.spans) {
            let line_text: String = line
                .iter()
                .map(|s| s.text.as_str())
                .collect::<Vec<_>>()
                .join(" ");
            if !line_text.trim().is_empty() {
                text.push_str(line_text.trim());
                text.push('\n');
            }
        }
        text.push('\n');
    }
    text
}

#[test]
fn every_fixture_pdf_parses_and_converts_to_all_targets() {
    assert!(!fixture_names().is_empty(), "no PDF fixtures found");
    for name in &fixture_names() {
        let path = fixtures_dir().join(name);
        let text = extract_text(&path);
        assert!(
            !text.trim().is_empty(),
            "{name}: layout extraction yielded no text"
        );
        for target in [Target::Text, Target::Markdown, Target::Docx, Target::Pdf] {
            let (out, _report) = convert(FormatId::PlainText, text.as_bytes(), target)
                .unwrap_or_else(|e| panic!("{name} -> {target:?}: {e}"));
            assert!(
                !out.is_empty(),
                "{name} -> {target:?} produced empty output"
            );
            match target {
                Target::Pdf => assert!(
                    out.starts_with(b"%PDF-1.7"),
                    "{name} -> PDF missing PDF header"
                ),
                Target::Docx => assert!(
                    out.starts_with(b"PK"),
                    "{name} -> DOCX missing OPC zip signature"
                ),
                Target::Text | Target::Markdown => {
                    std::str::from_utf8(&out)
                        .unwrap_or_else(|e| panic!("{name} -> {target:?} not UTF-8: {e}"));
                }
            }
        }
    }
}

#[test]
fn converted_markdown_keeps_fixture_headings() {
    let path = fixtures_dir().join("rich_styles.pdf");
    let text = extract_text(&path);
    let (out, _report) = convert(FormatId::PlainText, text.as_bytes(), Target::Markdown)
        .expect("rich_styles -> markdown");
    let out = std::str::from_utf8(&out).expect("markdown is UTF-8");
    for token in [
        "Quarterly Review",
        "Executive summary",
        "Française",
        "Español",
        "日本語",
    ] {
        assert!(
            out.contains(token),
            "markdown output missing {token:?}:\n{out}"
        );
    }
}
